import { createClient } from '@supabase/supabase-js'
import { revalidateTag } from 'next/cache'
import { headers } from 'next/headers'
import { NextRequest } from 'next/server'
import { describe, it, expect, vi, beforeEach, afterEach, type Mock } from 'vitest'

import { _handleRevalidateRequest } from './route'

// Mock Next.js modules
vi.mock('next/cache', () => ({
  revalidateTag: vi.fn(),
}))

vi.mock('next/headers', () => ({
  headers: vi.fn(),
}))

// Mock Supabase client
vi.mock('@supabase/supabase-js', () => ({
  createClient: vi.fn(),
}))

describe('_handleRevalidateRequest', () => {
  let mockDate: Date
  let originalEnv: NodeJS.ProcessEnv
  let mockSupabaseClient: {
    rpc: Mock
    from: Mock
  }

  beforeEach(() => {
    // Store the original environment
    originalEnv = { ...process.env }

    // Mock environment variables
    process.env.DOCS_REVALIDATION_KEYS = 'basic_key'
    process.env.DOCS_REVALIDATION_OVERRIDE_KEYS = 'override_key,other_override_key'
    process.env.NEXT_PUBLIC_SUPABASE_URL = 'http://localhost:3000'
    process.env.SUPABASE_SECRET_KEY = 'secret_key'

    // Mock current date
    mockDate = new Date('2023-01-01T12:00:00Z')
    vi.setSystemTime(mockDate)

    // Setup mock Supabase client
    mockSupabaseClient = {
      rpc: vi.fn(),
      from: vi.fn(() => ({
        insert: vi.fn().mockResolvedValue({ error: null }),
      })),
    }
    vi.mocked(createClient).mockReturnValue(mockSupabaseClient as any)
  })

  afterEach(() => {
    process.env = originalEnv
    vi.clearAllMocks()
    vi.useRealTimers()
  })

  it('should return 401 if Authorization header is missing', async () => {
    const request = new NextRequest('https://example.com', {
      method: 'POST',
    })

    vi.mocked(headers).mockReturnValue(new Headers(request.headers))

    const response = await _handleRevalidateRequest(request)
    expect(response.status).toBe(401)
    expect(await response.text()).toBe('Missing Authorization header')
  })

  it('should return 401 if Authorization header is invalid', async () => {
    const request = new NextRequest('https://example.com', {
      method: 'POST',
      headers: {
        Authorization: 'Bearer invalid_token',
      },
    })

    vi.mocked(headers).mockReturnValue(new Headers(request.headers))

    const response = await _handleRevalidateRequest(request)
    expect(response.status).toBe(401)
    expect(await response.text()).toBe('Invalid Authorization header')
  })

  it('should return 400 if request body is malformed', async () => {
    const request = new NextRequest('https://example.com', {
      method: 'POST',
      headers: {
        Authorization: 'Bearer basic_key',
      },
      body: JSON.stringify({ invalid: 'body' }),
    })

    vi.mocked(headers).mockReturnValue(new Headers(request.headers))

    const response = await _handleRevalidateRequest(request)
    expect(response.status).toBe(400)
    expect(await response.text()).toContain('Malformed request body')
  })

  it('should revalidate tags if request is valid with basic permissions', async () => {
    const request = new NextRequest('https://example.com', {
      method: 'POST',
      headers: {
        Authorization: 'Bearer basic_key',
      },
      body: JSON.stringify({ tags: ['tag1', 'tag2'] }),
    })

    vi.mocked(headers).mockReturnValue(new Headers(request.headers))

    mockSupabaseClient.rpc.mockResolvedValue({ data: [] })

    const response = await _handleRevalidateRequest(request)
    expect(response.status).toBe(204)
    expect(revalidateTag).toHaveBeenCalledTimes(2)
    expect(revalidateTag).toHaveBeenCalledWith('tag1')
    expect(revalidateTag).toHaveBeenCalledWith('tag2')
  })

  it('should return 429 if last revalidation was less than 6 hours ago with basic permissions', async () => {
    const request = new NextRequest('https://example.com', {
      method: 'POST',
      headers: {
        Authorization: 'Bearer basic_key',
      },
      body: JSON.stringify({ tags: ['tag1'] }),
    })

    vi.mocked(headers).mockReturnValue(new Headers(request.headers))

    const fiveHoursAgo = new Date(mockDate.getTime() - 5 * 60 * 60 * 1000)
    mockSupabaseClient.rpc.mockResolvedValue({
      data: [{ created_at: fiveHoursAgo.toISOString() }],
    })

    const response = await _handleRevalidateRequest(request)
    expect(response.status).toBe(429)
    expect(await response.text()).toContain('revalidated within the last 6 hours')
  })

  it('should revalidate if last revalidation was more than 6 hours ago with basic permissions', async () => {
    const request = new NextRequest('https://example.com', {
      method: 'POST',
      headers: {
        Authorization: 'Bearer basic_key',
      },
      body: JSON.stringify({ tags: ['tag1'] }),
    })

    vi.mocked(headers).mockReturnValue(new Headers(request.headers))

    const sevenHoursAgo = new Date(mockDate.getTime() - 7 * 60 * 60 * 1000)
    mockSupabaseClient.rpc.mockResolvedValue({
      data: [{ created_at: sevenHoursAgo.toISOString() }],
    })

    const response = await _handleRevalidateRequest(request)
    expect(response.status).toBe(204)
    expect(revalidateTag).toHaveBeenCalledWith('tag1')
  })

  it('should revalidate regardless of last revalidation time with override permissions', async () => {
    const request = new NextRequest('https://example.com', {
      method: 'POST',
      headers: {
        Authorization: 'Bearer override_key',
      },
      body: JSON.stringify({ tags: ['tag1'] }),
    })

    vi.mocked(headers).mockReturnValue(new Headers(request.headers))

    const oneHourAgo = new Date(mockDate.getTime() - 1 * 60 * 60 * 1000)
    mockSupabaseClient.rpc.mockResolvedValue({
      data: [{ created_at: oneHourAgo.toISOString() }],
    })

    const response = await _handleRevalidateRequest(request)
    expect(response.status).toBe(204)
    expect(revalidateTag).toHaveBeenCalledWith('tag1')
  })
})

import { load } from 'cheerio'
import { describe, expect, it } from 'vitest'

const REFERENCE_DOCS_URL = 'https://supabase.com/docs/reference'
// For dev testing: comment out above and uncomment below
// const REFERENCE_DOCS_URL = 'http://localhost:3001/docs/reference'

describe('prod smoke test: crawler pages return correct data', () => {
  /**
   * No special tricks required to spoof the user agent. Tests are correctly
   * detected as coming from bots. If they ever aren't, the `h1` test will fail
   * as a different `h1` is served to non-bots.
   */

  it('metadata: title, description, canonical, image', async () => {
    const result = await fetch(REFERENCE_DOCS_URL + '/javascript/rangelte')
    const text = await result.text()

    const $ = load(text)
    const title = $('title').text()
    expect(title).toBe('JavaScript: Less than or equal to a range | Supabase Docs')

    const metaDescription = $('meta[name="description"]')
    expect(metaDescription.attr('content')).toBe(
      'Supabase API reference for JavaScript: Less than or equal to a range'
    )

    const canonical = $('link[rel="canonical"]')
    expect(canonical.attr('href')).toBe('https://supabase.com/docs/reference/javascript/rangelte')

    const ogImage = $('meta[name="og:image"]')
    expect(ogImage.attr('content')).toBe('https://supabase.com/docs/img/supabase-og-image.png')

    const twitterImage = $('meta[name="twitter:image"]')
    expect(twitterImage.attr('content')).toBe('https://supabase.com/docs/img/supabase-og-image.png')
  })

  it('markdown pages', async () => {
    const result = await fetch(REFERENCE_DOCS_URL + '/javascript/introduction')
    const text = await result.text()

    const $ = load(text)
    const h1 = $('h1').text()
    expect(h1).toBe('JavaScript: Introduction')

    const firstPara = $('h1').next().text()
    expect(/JavaScript library/.test(firstPara)).toBe(true)
    expect(/supabase-js/.test(firstPara)).toBe(true)
  })

  it('function pages', async () => {
    const result = await fetch(REFERENCE_DOCS_URL + '/javascript/rangelte')
    const text = await result.text()

    const $ = load(text)
    const h1 = $('h1').text()
    expect(h1).toBe('JavaScript: Less than or equal to a range')

    const description = $('h1').next().text()
    expect(description).toBe(
      'Only relevant for range columns. Match only rows where every element in column is either contained in range or less than any element in range.'
    )

    const headings = [] as Array<string | undefined>
    $('h2').map(function () {
      headings.push($(this).attr('id'))
    })

    expect(headings.includes('parameters')).toBe(true)
    expect(headings.includes('examples')).toBe(true)
  })
})

